package com.phoenix.business.web;
import com.phoenix.business.domain.*; import com.phoenix.business.repository.*; import com.phoenix.business.security.JwtService; import com.phoenix.business.service.AuditService; import io.jsonwebtoken.Claims; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; import java.util.concurrent.*;
@RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController {private final UserRepository users;private final RevokedTokenRepository revoked;private final PasswordEncoder encoder;private final JwtService jwt;private final AuditService audit;private final Map<String,Attempts> attempts=new ConcurrentHashMap<>(); record Login(@NotBlank String username,@NotBlank String password){} record PasswordChange(@NotBlank String currentPassword,@NotBlank @Pattern(regexp="^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d).{10,72}$",message="must be 10+ characters with upper, lower and number") String newPassword){} record Attempts(int count,Instant until){}
@PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody Login q,jakarta.servlet.http.HttpServletRequest req){String key=req.getRemoteAddr()+":"+q.username().toLowerCase();Attempts a=attempts.get(key);if(a!=null&&a.count()>=5&&a.until().isAfter(Instant.now()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Too many attempts");User u=users.findByUsernameIgnoreCase(q.username()).filter(User::isActive).orElse(null);if(u==null||!encoder.matches(q.password(),u.getPasswordHash())){attempts.put(key,new Attempts(a==null?1:a.count()+1,Instant.now().plusSeconds(900)));throw new org.springframework.web.server.ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");}attempts.remove(key);u.setLastLoginAt(Instant.now());users.save(u);audit.record("USER_LOGIN","USER",u.getId(),"Successful login");return Map.of("accessToken",jwt.issue(u.getUsername(),u.getRole().name()),"expiresInSeconds",900,"user",Map.of("id",u.getId(),"username",u.getUsername(),"displayName",u.getDisplayName(),"role",u.getRole(),"forcePasswordChange",u.isForcePasswordChange()));}
@GetMapping("/me") public Map<String,Object> me(Authentication a){User u=users.findByUsernameIgnoreCase(a.getName()).orElseThrow();return Map.of("id",u.getId(),"username",u.getUsername(),"displayName",u.getDisplayName(),"role",u.getRole(),"forcePasswordChange",u.isForcePasswordChange());}
@PostMapping("/change-password") public void change(@Valid @RequestBody PasswordChange q,Authentication a){User u=users.findByUsernameIgnoreCase(a.getName()).orElseThrow();if(!encoder.matches(q.currentPassword(),u.getPasswordHash()))throw new IllegalArgumentException("Current password is incorrect");if(q.newPassword().equals(q.currentPassword()))throw new IllegalArgumentException("Choose a different password");if(q.newPassword().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>72)throw new IllegalArgumentException("Password must be at most 72 UTF-8 bytes");u.setPasswordHash(encoder.encode(q.newPassword()));u.setForcePasswordChange(false);users.save(u);audit.record("PASSWORD_CHANGED","USER",u.getId(),"Own password changed");}
@PostMapping("/logout") public void logout(@RequestHeader("Authorization") String h){Claims c=jwt.parse(h.substring(7));revoked.save(new RevokedToken(c.getId(),c.getExpiration().toInstant()));audit.record("USER_LOGOUT","USER",null,"Successful logout");}}
